import {
  CdkOverlayOrigin,
  ConnectedPosition,
  ConnectionPositionPair,
  FlexibleConnectedPositionStrategy,
  GlobalPositionStrategy,
  Overlay,
  OverlayConfig,
  OverlayContainer,
  OverlayModule,
  OverlayRef,
  OverlaySizeConfig,
  ScrollStrategyOptions,
} from '@angular/cdk/overlay';
import { CdkPortal, PortalModule } from '@angular/cdk/portal';
import { NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  ContentChild,
  EventEmitter,
  Input,
  Output,
  TemplateRef,
  ViewChild,
  booleanAttribute,
  inject,
  DOCUMENT,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { ESCAPE } from '@questrade/allspark-angular-components/core/utils';
import { BehaviorSubject, Observable, merge } from 'rxjs';
import { filter, map, takeUntil } from 'rxjs/operators';
import {
  QOverlayPositions,
  Q_HORIZONTAL_PRIORITY_POSITIONS,
  Q_OVERLAY_SUPPORTED_POSITIONS,
  Q_VERTICAL_PRIORITY_POSITIONS,
} from './overlay-position';
import { QOverlayPositionStrategy } from './types/overlay-position-strategy.type';
import { QOverlayPositionX } from './types/overlay-position-x.type';
import { QOverlayPositionY } from './types/overlay-position-y.type';
import { QOverlayPriorityPosition } from './types/overlay-priority-position.type';
import { QOverlayScrollStrategy } from './types/overlay-scroll-strategy.type';

@Component({
  selector: 'q-overlay',
  imports: [NgTemplateOutlet, OverlayModule, PortalModule],
  providers: [QDestroyService],
  templateUrl: './overlay.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QOverlayComponent {
  @Output() readonly opened = new EventEmitter<void>();
  @Output() readonly closed = new EventEmitter<undefined | KeyboardEvent | MouseEvent>();
  @Output() readonly overlayOriginChange = new EventEmitter<CdkOverlayOrigin>();

  @Input() top = '';
  @Input() bottom = '';
  @Input() left = '';
  @Input() right = '';
  @Input() offsetY = 4;
  @Input() offsetX = 4;
  @Input() width: number | string = '';
  @Input() minWidth: number | string = '';
  @Input() maxWidth: number | string = '';
  @Input() height: number | string = '';
  @Input() minHeight: number | string = '';
  @Input() maxHeight: number | string = '';
  @Input() yPosition: QOverlayPositionY = 'below';
  @Input() xPosition: QOverlayPositionX = 'start';
  @Input() positions: ConnectionPositionPair[] = [];
  @Input() overlayOrigin: CdkOverlayOrigin | null = null;
  @Input() panelClass: string | string[] = 'q-overlay-panel';
  @Input() backdropClass = 'cdk-overlay-transparent-backdrop';
  @Input() scrollStrategy: QOverlayScrollStrategy = 'reposition';
  @Input() closeAnimationDone = new BehaviorSubject<boolean>(false);
  @Input() priorityPositions: QOverlayPriorityPosition = 'vertical';
  @Input({ transform: booleanAttribute }) closeOnBackdropClick = true;
  @Input({ transform: booleanAttribute }) flexibleDimensions = false;
  @Input({ transform: booleanAttribute }) disableClose = false;
  @Input({ transform: booleanAttribute }) hasBackdrop = true;
  @Input({ transform: booleanAttribute }) closeOnEsc = true;

  @ContentChild('overlayContentTemplate')
  _overlayContentTemplate!: TemplateRef<HTMLTemplateElement>;

  @ViewChild('overlayTemplatePortal') _overlayTemplatePortal!: CdkPortal;

  private _isOpened$ = new BehaviorSubject<boolean>(false);
  isOpened$: Observable<boolean> = this._isOpened$.asObservable();
  private _overlayRef: OverlayRef | null = null;
  private readonly _overlay = inject(Overlay);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _scrollStrategies = inject(ScrollStrategyOptions);
  private readonly _overlayContainer = inject(OverlayContainer);
  private readonly _document = inject(DOCUMENT);

  open(): void {
    this._createAndOpenOverlay();

    this._isOpened$.next(true);
    this.opened.emit();
  }

  close(event?: KeyboardEvent | MouseEvent): void {
    this._overlayRef?.detach();
    this._overlayRef?.dispose();

    this._isOpened$.next(false);
    this.closed.emit(event);
  }

  detachBackdrop(): void {
    this._overlayRef?.detachBackdrop();
  }

  toggle(): void {
    if (!this._isOpened$.getValue()) {
      this.open();
    } else {
      this.close();
    }
  }

  updateSize(sizeConfig: OverlaySizeConfig): void {
    if (!this._overlayRef) return;

    this._overlayRef.updateSize(sizeConfig);
  }

  updateScrollStrategy(strategy: QOverlayScrollStrategy): void {
    this._overlayRef?.updateScrollStrategy(this._scrollStrategies[strategy]());
  }

  updatePositionStrategy(strategy: QOverlayPositionStrategy): void {
    if (!this._overlayRef) return;

    if (strategy === 'connected' && this.overlayOrigin) {
      this._overlayRef.updatePositionStrategy(
        this._getFlexibleConnectedPositionStrategy(this.overlayOrigin),
      );
    } else if (strategy === 'global') {
      this._overlayRef.updatePositionStrategy(this._getGlobalPositionStrategy());
    }
  }

  get isOpened(): boolean {
    return this._isOpened$.getValue();
  }

  private _createAndOpenOverlay(): void {
    this._relocateOverlayContainer();

    const overlayConfig = new OverlayConfig({
      hasBackdrop: this.hasBackdrop,
      backdropClass: this.backdropClass,
      panelClass: this.panelClass,
      width: `var(--awds-overlay-panel-width ${this.width ? ', ' + this.width + 'px' : ''})`,
      minWidth: `var(--awds-overlay-panel-min-width ${this.minWidth ? ', ' + this.minWidth + 'px' : ''})`,
      maxWidth: `var(--awds-overlay-panel-max-width ${this.maxWidth ? ', ' + this.maxWidth + 'px' : ''})`,
      height: `var(--awds-overlay-panel-height ${this.height ? ', ' + this.height + 'px' : ''})`,
      maxHeight: `var(--awds-overlay-panel-max-height ${this.maxHeight ? ', ' + this.maxHeight + 'px' : ''})`,
      minHeight: `var(--awds-overlay-panel-min-height ${this.minHeight ? ', ' + this.minHeight + 'px' : ''})`,
      scrollStrategy: this._scrollStrategies[this.scrollStrategy](),
      positionStrategy: this.overlayOrigin
        ? this._getFlexibleConnectedPositionStrategy(this.overlayOrigin)
        : this._getGlobalPositionStrategy(),
    });

    this._overlayRef = this._overlay.create(overlayConfig);

    this._getCloseStream(this._overlayRef)
      .pipe(takeUntil(this._destroy$))
      .subscribe((event: undefined | KeyboardEvent | MouseEvent) => {
        if (!event) return;

        event.preventDefault();

        if (!this.disableClose) {
          this.close(event);
        }
      });

    this._overlayRef.attach(this._overlayTemplatePortal);
  }

  private _relocateOverlayContainer(): void {
    if (this.overlayOrigin) {
      const originElement = this.overlayOrigin.elementRef.nativeElement;
      const dialogContainer = originElement.closest('dialog[q-dialog], dialog[qDialog]');
      const popoverContainer = originElement.closest('[popover][q-popover], [popover][qPopover]');
      const overlayContainer = this._overlayContainer.getContainerElement();

      if (dialogContainer?.contains(originElement)) {
        overlayContainer.parentNode?.removeChild(overlayContainer);
        dialogContainer.appendChild(overlayContainer);
      } else if (popoverContainer?.contains(originElement)) {
        overlayContainer.parentNode?.removeChild(overlayContainer);
        popoverContainer.appendChild(overlayContainer);
      } else if (overlayContainer.parentNode !== this._document.body) {
        this._document.body.appendChild(overlayContainer);
      }
    }
  }

  private _getGlobalPositionStrategy(): GlobalPositionStrategy {
    const ps = this._overlay.position().global().centerHorizontally().centerVertically();

    if (this.top) ps.top(this.top);
    if (this.bottom) ps.bottom(this.bottom);
    if (this.left) ps.left(this.left);
    if (this.right) ps.right(this.right);

    return ps;
  }

  private _getFlexibleConnectedPositionStrategy(
    overlayOrigin: CdkOverlayOrigin,
  ): FlexibleConnectedPositionStrategy {
    return this._overlay
      .position()
      .flexibleConnectedTo(overlayOrigin.elementRef)
      .withLockedPosition()
      .withFlexibleDimensions(this.flexibleDimensions)
      .withPositions(
        (this.positions?.length
          ? this.positions
          : this._getDefaultPositions()) as ConnectedPosition[],
      );
  }

  private _getDefaultPositions(): ConnectionPositionPair[] {
    let prioritizedPositions: QOverlayPositions[] =
      this.priorityPositions === 'horizontal'
        ? Q_HORIZONTAL_PRIORITY_POSITIONS
        : Q_VERTICAL_PRIORITY_POSITIONS;

    const selectedPosition = `${this.yPosition}-${this.xPosition}` as QOverlayPositions;

    prioritizedPositions = [
      selectedPosition,
      ...prioritizedPositions.filter((position) => position !== selectedPosition),
    ];

    const positions: ConnectionPositionPair[] = [];

    prioritizedPositions.forEach((position) => {
      positions.push({
        ...Q_OVERLAY_SUPPORTED_POSITIONS[position],
        offsetX: (Q_OVERLAY_SUPPORTED_POSITIONS[position].offsetX ?? 0) * this.offsetX,
        offsetY: (Q_OVERLAY_SUPPORTED_POSITIONS[position].offsetY ?? 0) * this.offsetY,
      });
    });

    return positions;
  }

  private _getCloseStream(
    overlayRef: OverlayRef,
  ): Observable<undefined | KeyboardEvent | MouseEvent> {
    let closeStream$: Observable<undefined | KeyboardEvent | MouseEvent> = overlayRef
      .detachments()
      .pipe(map(() => undefined));

    if (this.closeOnBackdropClick) {
      closeStream$ = merge(closeStream$, overlayRef.backdropClick());
    }

    if (this.closeOnEsc) {
      closeStream$ = merge(
        closeStream$,
        overlayRef.keydownEvents().pipe(filter((event) => event.code === ESCAPE)),
      );
    }

    return closeStream$;
  }

  get closeStream(): Observable<undefined | KeyboardEvent | MouseEvent> | null {
    return this._overlayRef && this._getCloseStream(this._overlayRef);
  }
}
